import os from "os";

/**
 * Detects whether the terminal supports Unicode characters.
 *
 * Returns false on Windows (`os.type() === "Windows_NT"`) because there is no
 * reliable way to detect console Unicode support there. On all other systems,
 * the locale environment variables are inspected in priority order
 * (`LC_ALL`, then `LC_CTYPE`, then `LANG`) and the resolved value is tested
 * against `/UTF-?8$/i` (e.g. "en_US.UTF-8", "UTF-8", "de_DE.utf8").
 */
export function hasUnicode(): boolean {
  // Recent Win32 platforms (>XP) CAN support unicode in the console but
  // don't have to, and in non-english locales often use traditional local
  // code pages. There's no reliable way to figure this out, so default to
  // false on Windows.
  if (os.type() === "Windows_NT") {
    return false;
  }

  const isUTF8 = /UTF-?8$/i;
  const ctype = process.env.LC_ALL || process.env.LC_CTYPE || process.env.LANG;
  return isUTF8.test(ctype ?? "");
}
