/**
 * Describes the color support level of a terminal.
 *
 *  - `level`: 0 = none, 1 = basic (16 colors), 2 = 256 colors, 3 = 16M colors
 *  - `hasBasic`: whether at least basic (16 color) support is available
 *  - `has256`: whether 256 color support is available
 *  - `has16m`: whether 16 million (truecolor) support is available
 */
export interface ColorSupportResult {
  level: number;
  hasBasic: boolean;
  has256: boolean;
  has16m: boolean;
}

function hasNone(): ColorSupportResult {
  return { level: 0, hasBasic: false, has256: false, has16m: false };
}

function hasBasic(): ColorSupportResult {
  return { level: 1, hasBasic: true, has256: false, has16m: false };
}

function has256(): ColorSupportResult {
  return { level: 2, hasBasic: true, has256: true, has16m: false };
}

function has16m(): ColorSupportResult {
  return { level: 3, hasBasic: true, has256: true, has16m: true };
}

/**
 * Detects the color support level of the given stream (defaulting to
 * `process.stdout`), taking the platform and various environment variables
 * into account.
 */
export function colorSupport(
  stream: { isTTY?: boolean } = process.stdout as { isTTY?: boolean }
): ColorSupportResult {
  const env = process.env;
  const term = env.TERM || "";
  const platform = process.platform;

  if (stream && !stream.isTTY) {
    return hasNone();
  }

  if (term === "dumb" && !env.COLORTERM) {
    return hasNone();
  }

  if (platform === "win32") {
    return hasBasic();
  }

  if (env.TMUX) {
    return has256();
  }

  if (env.TEAMCITY_VERSION) {
    return hasNone();
  }

  if (env.CI) {
    if (env.TRAVIS) {
      return has256();
    }
    return hasNone();
  }

  // TODO: add more term programs
  switch (env.TERM_PROGRAM) {
    case "iTerm.app": {
      const ver = env.TERM_PROGRAM_VERSION || "0.";
      if (/^[0-2]\./.test(ver)) {
        return has256();
      }
      return has16m();
    }

    case "HyperTerm":
    case "Hyper":
      return has16m();

    case "MacTerm":
      return has16m();

    case "Apple_Terminal":
      return has256();
  }

  if (/^xterm-256/.test(term)) {
    return has256();
  }

  if (/^screen|^xterm|^vt100|color|ansi|cygwin|linux/i.test(term)) {
    return hasBasic();
  }

  if (env.COLORTERM) {
    return hasBasic();
  }

  return hasNone();
}
